function boughPts(x, y, a, L, cur, n)
  local pts = {{x, y}}
  local aa, step = a, L / n
  for i = 1, n do
    aa = aa + cur / n
    x = x + math.cos(aa) * step
    y = y + math.sin(aa) * step
    pts[#pts+1] = {x, y}
  end
  return pts
end

function alongPt(pts, t)
  local n = #pts - 1
  local f = t * n
  local i = math.floor(f) + 1
  if i > n then i = n end
  local u = f - (i - 1)
  return lerp(pts[i][1], pts[i + 1][1], u), lerp(pts[i][2], pts[i + 1][2], u)
end

function growBough(x, y, a, L, w, cur, depth, thick, thin)
  local pts = boughPts(x, y, a, L, cur, 4)
  local last = {pts = pts, w = w, a = a + cur, L = L}
  if w > 5.2 then thick[#thick + 1] = last else thin[#thin + 1] = last end
  if depth <= 0 then return end
  local nb = (depth >= 2) and 3 or 2
  for i = 1, nb do
    local t = clamp((i - 0.4) / nb + rand(-0.11, 0.11), 0.16, 0.94)
    local px, py = alongPt(pts, t)
    local side = (math.random(0, 1) == 0) and -1 or 1
    local na = last.a + side * rand(0.5, 1.15)
    local nl = L * rand(0.30, 0.52) * (1 - 0.28 * t)
    growBough(px, py, na, nl, w * rand(0.38, 0.54),
              cur * rand(-0.7, 0.7) + side * rand(0.1, 0.55), depth - 1, thick, thin)
  end
end

function oakBuild(spec)
  local thick, thin = {}, {}
  local tp = boughPts(spec.bx, spec.by, -1.5708 + spec.lean, spec.by - spec.forkY, spec.cur, 6)
  thick[#thick + 1] = {pts = tp, w = spec.tw}
  for i = 1, #spec.boughs do
    local b = spec.boughs[i]
    growBough(b[1], b[2], b[3], b[4], b[5], b[6], b[7], thick, thin)
  end
  return thick, thin
end

